<script setup lang="ts">
import { resolveAuthor } from "../composables/useAuthorAliases";
import {ref,computed,onMounted} from 'vue';
import {invoke} from '@tauri-apps/api/core';
import type {Project} from '../types';
import VersionHistory from '../components/VersionHistory.vue';
interface Version{id:string;project:Project;starred:boolean}
const archiveGroups=ref<Project[]>([]);
const versions=ref<Version[]>([]),selected=ref<Project|null>(null),search=ref(''),error=ref('');
const showBackups=ref(false),selectedStarredOnly=ref(true);
const backupGroups=computed(()=>{const groups=new Map<string,{project:Project;count:number}>();for(const version of versions.value){if(version.starred)continue;const group=groups.get(version.project.id);if(group)group.count++;else groups.set(version.project.id,{project:version.project,count:1});}return [...groups.values()];});
const starred=computed(()=>versions.value.filter(v=>v.starred).filter(v=>JSON.stringify([v.project.name,v.project.title,v.project.author,v.project.fandom,v.project.modder,v.project.id]).toLowerCase().includes(search.value.toLowerCase())));
function groupLabel(version:Version){const group=archiveGroups.value.find(p=>p.id===version.project.id);return group?.title||group?.name||version.project.name;}
async function load(){try{const [editions,labels]=await Promise.all([invoke<Version[]>('list_archives'),invoke<Project[]>('list_archive_groups')]);versions.value=editions;archiveGroups.value=labels||[];}catch(e){error.value=String(e);}}
onMounted(load);
</script>
<template><div class="archive-view"><h1>Archives</h1><p>Starred editions only. Automatic backups remain available through Version history or Manage automatic backups.</p><input v-model="search" aria-label="Search archives" placeholder="Search starred editions…"/><p v-if="error" role="alert">{{error}}</p><p v-if="!starred.length">No matching starred editions.</p><button class="btn-secondary backup-toggle" :aria-expanded="showBackups" @click="showBackups=!showBackups">Manage automatic backups</button><div v-if="showBackups" class="backup-groups"><p>Unstarred backup groups, including editions whose library card was removed. Opening a group does not restore or replace a card.</p><p v-if="!backupGroups.length">No automatic backup groups.</p><div v-for="group in backupGroups" :key="group.project.id" class="backup-group"><span>{{group.project.title||group.project.name}} · {{group.count}} unstarred · Group {{group.project.id.slice(0,8)}}</span><button class="btn-secondary" @click="selectedStarredOnly=false;selected=group.project">Browse backups</button></div></div><section v-for="version in starred" :key="version.id"><div><h2>{{version.project.title||version.project.name}}</h2><p>{{resolveAuthor(version.project.author)}}<template v-if="version.project.modder"> · Modder: {{version.project.modder}}</template></p><p class="group-id">{{groupLabel(version)}} · Edition {{version.id.slice(0,8)}}</p></div><button class="btn-primary" @click="selectedStarredOnly=true;selected=version.project">Browse / open editions</button></section><VersionHistory v-if="selected" :project="selected" :starred-only="selectedStarredOnly" @close="selected=null;load()" @restored="load"/></div></template>
<style scoped>.backup-toggle{display:block;margin:14px 0}.backup-groups{padding:12px;border:1px solid var(--border);border-radius:8px}.backup-group{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:10px 0;flex-wrap:wrap}.archive-view{padding:28px;overflow:auto}input{background:var(--input-bg);color:var(--text);border:1px solid var(--border);border-radius:8px;padding:10px;width:min(500px,100%)}section{display:flex;justify-content:space-between;align-items:center;gap:16px;padding:16px 0;border-bottom:1px solid var(--border)}h2{font-size:1.1rem}p{color:var(--muted)}@media(max-width:600px){section{align-items:stretch;flex-direction:column}}</style>
